import React, { useState, useEffect } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Table from '../../../components/ui/Table/Table';
import api from '../../../api/api';

const ListAdminsPage = () => {
  const [admins, setAdmins] = useState([]);
  const headers = [
    { key: 'id', label: 'ID' },
    { key: 'name', label: 'Nome' },
    { key: 'email', label: 'Email' },
    { key: 'created_at', label: 'Data de Criação' }
  ];

  useEffect(() => {
    const fetchAdmins = async () => {
      try {
        const response = await api.get('/admins');
        // Formata a data para ser mais legível
        const formattedAdmins = response.data.map(admin => ({
          ...admin,
          created_at: new Date(admin.created_at).toLocaleDateString('pt-BR')
        }));
        setAdmins(formattedAdmins);
      } catch (error) {
        console.error("Erro ao buscar administradores:", error);
      }
    };
    fetchAdmins();
  }, []);

  return (
    <ContentWrapper title="Listar Admins Nível 1">
      <Table headers={headers} data={admins} />
    </ContentWrapper>
  );
};

export default ListAdminsPage;
